import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
import {CreatorRollBridge} from '../../apps/room3d/chibi/CreatorRollBridge';
import {decodeParts,createVisitor} from '../../apps/room3d/chibi/visitor';
import {mountHomeEditor} from '../../apps/room3d/editor.js';import {createHome} from '../../apps/room3d/model.js';import {gamingPreset} from '../../apps/room3d/gaming.js';import '../../apps/room3d/editor.css';
function Fixture(){const [request,setRequest]=useState(0);return <><div id="home"/><CreatorRollBridge request={request} onReady={()=>setRequest(1)} onError={console.error} onResult={async result=>{const w=window as any;if(w.__loading)return;w.__loading=true;const c=await fetch('/room3d/catalog.json').then(r=>r.json()),home=createHome(c),kind=new URLSearchParams(location.search).get('kind')||'stream';home.rooms[0].name='电竞小屋';home.rooms[0].items=kind==='empty'?[]:gamingPreset(kind,c);const editor=await mountHomeEditor(document.querySelector('#home')!,{assetBase:new URL('/room3d/',location.href).href,initialState:home});const visitor=await createVisitor(await decodeParts(result));editor.setVisitor!(visitor);w.__visitor=visitor;w.__homeEditor=editor;w.render_game_to_text=()=>JSON.stringify(editor.inspect!());w.advanceTime=(ms:number)=>editor.advanceTime!(ms);if(new URLSearchParams(location.search).has('panel'))(document.querySelector('[data-panel="chibi"]') as HTMLButtonElement).click();}}/></>;}createRoot(document.querySelector('#root')!).render(<Fixture/>);
